            <template x-if="form.items.length"><div class="mt-3"><template x-for="(it, i) in form.items" :key="i"><div class="flex items-center gap-2 py-1 text-sm"><span class="flex-1" x-text="it.product_name"></span><span class="w-16 text-center" x-text="'x'+it.quantity"></span><span class="w-20 text-right text-gray-600" x-text="'$'+(it.quantity*it.unit_price).toFixed(2)"></span><button type="button" @click="form.items.splice(i,1)" class="text-red-400 hover:text-red-600 p-1"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button></div></template></div></template></div>
