@push('scripts')<script>function prData(){return{pager:{loading:true,items:[],currentPage:1,perPage:10,total:0,totalPages:1,get visiblePages(){return[]},fetchPage(){return Promise.resolve(false)},setSearch(){},refresh(){return Promise.resolve(false)},goToPage(){},changePerPage(){}},suppliers:[],products:[],search:'',filterStatus:'',modalOpen:false,saving:false,form:{supplier_id:'',return_date:new Date().toISOString().split('T')[0],reason:'',items:[]},newItem:{product_id:'',quantity:1,unit_price:0,reason:''},errors:{},async init(){try{this.pager=Alpine.store('pager').create({endpoint:'/api/v1/purchase-return',perPage:10})}catch(e){this.pager.loading=false;return}this.fetchDeps();this.pager.fetchPage()},doSearch(){var p={search:this.search||undefined};if(this.filterStatus)p.status=this.filterStatus;this.pager.setSearch(p)},async fetchDeps(){try{var d=await Alpine.store('api').get('/api/v1/supplier',{per_page:500});if(d&&d.status)this.suppliers=Array.isArray(d.data)?d.data:(d.data?.data||[]);var m=await Alpine.store('api').get('/api/v1/material',{per_page:500});if(m&&m.status)this.products=Array.isArray(m.data)?m.data:(m.data?.data||[])}catch(e){}},openAddModal(){this.form={supplier_id:'',return_date:new Date().toISOString().split('T')[0],reason:'',items:[]};this.errors={};this.modalOpen=true},closeModal(){this.modalOpen=false},addItem(){if(!this.newItem.product_id||!this.newItem.quantity)return;var p=this.products.find(function(p){return p.id==this.newItem.product_id},this);this.form.items.push({product_id:this.newItem.product_id,product_name:p?p.material_name:'Product',quantity:parseInt(this.newItem.quantity),unit_price:parseFloat(this.newItem.unit_price)||parseFloat(p?p.price:0),reason:this.newItem.reason});this.newItem={product_id:'',quantity:1,unit_price:0,reason:''}},async saveReturn(){if(!this.form.supplier_id){this.errors.supplier_id='Select a supplier';return}if(!this.form.items.length){Alpine.store('toast').error('Add at least one item');return}this.saving=true;try{var d=await Alpine.store('api').post('/api/v1/purchase-return',{...this.form,items:this.form.items.map(function(i){return{product_id:i.product_id,quantity:i.quantity,unit_price:i.unit_price,reason:i.reason}})});if(d.status){Alpine.store('toast').success('Return created');this.closeModal();this.pager.refresh()}}catch(e){Alpine.store('toast').error(e.message||'Failed')}finally{this.saving=false}}}}</script>@endpush
